  let lastReason = null;
  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
    if (signal && signal.aborted) {
      return { ok: false, cancelled: true, error: lastReason };
    }
    const record = makeRecord(attempt);
    let returned;
    try {
      returned = await implementation(...makeArgs(attempt));
    } catch (error) {
      lastReason = describeError(error);
      record.error = lastReason;
    }
    if (record.error === null) {
      try {
        returned = structuredClone(returned);
      } catch {
        lastReason = `${cloneErrorLabel} returned a value that cannot be structured-cloned`;
        record.error = lastReason;
